package com.tencent.shadow.core.loader.managers;import android.content.*;import android.util.Pair;import com.tencent.shadow.core.runtime.*;public class ComponentManager {public final PluginServiceManager delegate=new PluginServiceManager();public Pair<Boolean,Boolean> bindService(ShadowContext context,Intent i,ServiceConnection c,int f){if(i.plugin){delegate.bindPluginService(i,c,f);return new Pair<>(true,true);}return new Pair<>(false,false);}public Pair<Boolean,Object> unbindService(ShadowContext c,ServiceConnection conn){return new Pair<>(delegate.unbindPluginService(conn),null);}}